using Godot;
using System;
using System.Collections.Generic;

/// <summary>
/// The clickable shape of every Spine attachment: a small bitmap of the artwork plus the
/// box it covers, so a click can be told apart from the empty space around a Capoo.
/// The data is generated by tools/gen_hit_shapes.py into assets/data/hit_shapes.bin.
/// The shapes live in the space of the skeleton, the same space the meshes are drawn in.
/// </summary>
public class HitShape
{
	public const int MaskSize = 64;

	/// <summary>The box the shape covers, in the space of the skeleton.</summary>
	public Rect2 Box;

	private readonly byte[] mask;

	public HitShape(Rect2 box, byte[] mask)
	{
		Box = box;
		this.mask = mask;
	}

	/// <summary>True if the point (in the space of the skeleton) is on the artwork.</summary>
	public bool Contains(Vector2 local)
	{
		if (Box.Size.X <= 0 || Box.Size.Y <= 0) return false;
		if (local.X < Box.Position.X || local.X > Box.End.X) return false;
		if (local.Y < Box.Position.Y || local.Y > Box.End.Y) return false;
		float u = (local.X - Box.Position.X) / Box.Size.X;
		float v = (local.Y - Box.Position.Y) / Box.Size.Y;
		int col = Mathf.Clamp((int)(u * MaskSize), 0, MaskSize - 1);
		int row = Mathf.Clamp((int)(v * MaskSize), 0, MaskSize - 1);
		int index = row * (MaskSize / 8) + col / 8;
		return (mask[index] & (1 << (col % 8))) != 0;
	}
}

/// <summary>Loads the clickable shapes of all the Spine skeletons.</summary>
public static class HitShapes
{
	private const string DataPath = "res://assets/data/hit_shapes.bin";
	private static readonly byte[] Magic = System.Text.Encoding.ASCII.GetBytes("CAPOO_HITSHAPES2");

	// skeleton -> slot (by index) -> attachment -> shape
	private static Dictionary<string, List<Dictionary<string, HitShape>>> shapes;

	/// <summary>The shapes of one skeleton, by slot and by attachment.</summary>
	public static List<Dictionary<string, HitShape>> For(string skeletonName)
	{
		if (skeletonName == null) return null;
		Load();
		return shapes.TryGetValue(skeletonName, out var result) ? result : null;
	}

	private static void Load()
	{
		if (shapes != null) return;
		shapes = new Dictionary<string, List<Dictionary<string, HitShape>>>();

		if (!FileAccess.FileExists(DataPath))
		{
			GD.PrintErr($"Missing hit shape data: {DataPath}");
			return;
		}
		using var file = FileAccess.Open(DataPath, FileAccess.ModeFlags.Read);
		if (file == null)
		{
			GD.PrintErr($"Cannot read hit shape data: {DataPath}");
			return;
		}

		var data = file.GetBuffer((int)file.GetLength());
		var reader = new Reader(data);
		for (int i = 0; i < Magic.Length; i++)
		{
			if (reader.Byte() != Magic[i])
			{
				GD.PrintErr("Hit shape data has the wrong format.");
				shapes = null;
				return;
			}
		}

		int skeletonCount = (int)reader.U32();
		for (int i = 0; i < skeletonCount; i++)
		{
			string skeletonName = reader.String();
			int slotCount = reader.U16();
			var skeleton = new List<Dictionary<string, HitShape>>(slotCount);
			for (int j = 0; j < slotCount; j++)
			{
				int attachmentCount = reader.U16();
				var slot = new Dictionary<string, HitShape>();
				for (int k = 0; k < attachmentCount; k++)
				{
					string attachmentName = reader.String();
					float left = reader.Float();
					float bottom = reader.Float();
					float right = reader.Float();
					float top = reader.Float();
					var box = new Rect2(left, bottom, right - left, top - bottom);
					var mask = reader.Bytes(HitShape.MaskSize * HitShape.MaskSize / 8);
					slot[attachmentName] = new HitShape(box, mask);
				}
				skeleton.Add(slot);
			}
			shapes[skeletonName] = skeleton;
		}
	}

	/// <summary>Reads the little binary format of the shape file.</summary>
	private class Reader
	{
		private readonly byte[] data;
		private int at;

		public Reader(byte[] data) => this.data = data;

		public byte Byte() => data[at++];

		public ushort U16()
		{
			ushort value = (ushort)(data[at] | (data[at + 1] << 8));
			at += 2;
			return value;
		}

		public uint U32()
		{
			uint value = (uint)(data[at] | (data[at + 1] << 8) | (data[at + 2] << 16) | (data[at + 3] << 24));
			at += 4;
			return value;
		}

		public float Float()
		{
			float value = BitConverter.ToSingle(data, at);
			at += 4;
			return value;
		}

		public byte[] Bytes(int count)
		{
			var result = new byte[count];
			System.Array.Copy(data, at, result, 0, count);
			at += count;
			return result;
		}

		public string String()
		{
			int length = U16();
			return System.Text.Encoding.UTF8.GetString(Bytes(length));
		}
	}
}
